import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402

CACHE = os.path.expanduser("~/Library/Group Containers/6N38VWS5BX.ru.keepcoder.Telegram/appstore")


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Quit Telegram ...")
  run("osascript", "-e", 'quit app "Telegram"')

  helpers.print_header("Cleaning Telegram cache ...")
  run("find", CACHE, "-type", "f", "-name", "telegram-*", "-size", "+1024k", "-delete")

  helpers.print_header("Starting Telegram ...")
  run("open", "-a", "Telegram")


if __name__ == "__main__":
  main()
